import React, { useState } from 'react';
import {DataGrid} from '@mui/x-data-grid';
import { configData } from './config';
const columns = [
{field: 'id', headerName: 'ID', width:90},
{field: 'firstName', headerName: 'First Name', width:150},
{field: 'lastName', headerName: 'Last Name', width:150},
];

const rows = [
    {id:1, lastName: 'snow', firstName: 'Jon'},
    {id:2, lastName: 'Jason', firstName: 'Ho'},
];

const SkillTable =() =>{
    const [rows, setRows]=useState([]);
    const [selectedId, setSelectedId]= useState('');

    const handleAddRow =() => {
        const selectedData = configData.find(item => item.id.toString()===selectedId);
        if(selectedData){
            setRows([...rows,{id: rows.length+1,...selectedData}]);
        }
        setSelectedId(''); //reset delection
    };

    return (
        <div>
            <select value={selectedId} onChange={(e)=> setSelectedId(e.target.value)}
                style={{marginBottom: '10px'}}
                >
                    <option value="">Select an ID</option>
                    {configData.map(({id})=>(
                        <option key={id} value={id}>
                            {id}
                        </option> 
                    ))}
                </select>
                <button onClick={handleAddRow} disables={!selectedId}>Add Row</button>
            
            <DataGrid
                rows={rows}
                columns={columns}
                pageSize={5}
                rowsPerPageOptions={[5]}
                checkboxSelection
                disableSelectionOnClick
            />
        </div>
    );
};

export default SkillTable;